#!/usr/bin/env python3
"""Generate Arabic C1 Unit 10 synthesis with zero new deliberate lexical targets in all six passages."""
from __future__ import annotations
import json,re,unicodedata
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'reading/arabic/c1/passages.jsonl';LEX=ROOT/'reading/lexicons/arabic.jsonl'
AR_DIAC=re.compile(r'[\u0610-\u061a\u064b-\u065f\u0670\u06d6-\u06ed]')
def norm(s):return AR_DIAC.sub('',unicodedata.normalize('NFC',str(s or '')).replace('ـ','').strip())
def lexicon():
 d={}
 for line in LEX.read_text(encoding='utf-8').splitlines():
  if line.strip():r=json.loads(line);d.setdefault(norm(r.get('form','')),r)
 return d
def review(f,s,rep,d):
 r=d.get(norm(f))
 if not r:raise KeyError(f'cleared review form missing: {f}')
 return {'id':f"ar-r{r['rank']}",'form':f,'review_stage':s,'representation':rep}
def qa(items):
 q=[];a=[]
 for i,(typ,p,ans) in enumerate(items,1):
  q.append({'id':f'q{i}','type':typ,'prompt':p,'answer_id':f'a{i}'})
  a.append({'id':f'a{i}','question_id':f'q{i}','answer':ans,'explanation':''})
 if len(q)!=10:raise ValueError('ten questions required')
 return q,a
